#include "CloseToHSL/Core/Runtime/Events/Traps/YAKSys_Hybrid_CPU.Core.TrapPolicyBitmap.h"
#include <cassert>
using namespace YAKSys_Hybrid_CPU::Core;
int main(){ TrapPolicyBitmap b; auto op=TrapRequest::ForInstruction(42,1); assert(!b.Evaluate(op)->ShouldTrap); b.EnableInstruction(42); auto epoch=b.getPolicyEpoch(); b.EnableInstruction(42); assert(b.getPolicyEpoch()==epoch); assert(b.Evaluate(op)->Kind==NeutralTrapResultKind::InstructionIntercept); b.EnableCsr(5); assert(b.Evaluate(TrapRequest::ForCsr(5,TrapAccessType::Read,1))->Kind==NeutralTrapResultKind::CsrIntercept); b.EnableMemoryRange(100,10,TrapAccessMask::Read); assert(b.Evaluate(TrapRequest::ForMemory(109,1,TrapAccessType::Read,1))->Kind==NeutralTrapResultKind::MemoryIntercept); assert(!b.Evaluate(TrapRequest::ForMemory(110,1,TrapAccessType::Read,1))->ShouldTrap); assert(!b.Evaluate(TrapRequest::ForMemory(100,1,TrapAccessType::Write,1))->ShouldTrap); b.EnableCompatibilityOperation(3); assert(b.Evaluate(TrapRequest::ForCompatibilityOperation(3,0,1))->Kind==NeutralTrapResultKind::CompatibilityOperationIntercept); b.EnableLaneOperation(6,22); assert(b.Evaluate(TrapRequest::ForLaneOperation(6,22,1))->Kind==NeutralTrapResultKind::LaneOperationIntercept); assert(!b.Evaluate(TrapRequest::ForLaneOperation(6,23,1))->ShouldTrap); b.EnableLane(7); assert(b.Evaluate(TrapRequest::ForLaneOperation(7,23,1))->ShouldTrap); b.Clear(); assert(!b.Evaluate(op)->ShouldTrap); }
